function BattleRoleInfoGroup:SetBuffSkillStatus(funcAdd, funcCancel, skillCard)
    if not self.isMyPlayerGroup then return end     -- 现在的规则是不能给队友加buff

    for i, roleNode in ipairs(self.listRoleInfo) do
        roleNode:SetEventBuffSkill(funcAdd, function() 
            self:SetCommonStatus()
            self.controller.gameObject.transform:DOScale(1, 0.3)
        end, skillCard)
    end
    self.funcCancel = funcCancel
    self.controller.gameObject.transform:DOScale(1.2, 0.3)
    if self.RT_BackInteractable ~= nil then
        KTool.SetActive(self.RT_BackInteractable.gameObject,true)
    end
end

function BattleRoleInfoGroup:SetCommonStatus()
    if IsNull(self.listRoleInfo) then return end
    if IsNull(self.RT_BackInteractable) then return end
    for i, roleNode in ipairs(self.listRoleInfo) do
        roleNode:SetEventShowRoleInfo()
    end
    -- self.controller.gameObject.transform:DOScale(1, 0.3)
    if self.RT_BackInteractable ~= nil then
        KTool.SetActive(self.RT_BackInteractable.gameObject,false)
    end
end

function BattleRoleInfoGroup:ResetCommonStatus()
    if IsNull(self.listRoleInfo) then return end
    for i, roleNode in ipairs(self.listRoleInfo) do
        roleNode:SetEventShowRoleInfo()
    end
end

