function BattleRoleInfoGroup:InitRoleInfoNode(data)
    for i = 1, #data do
        if IsNull(data[i].id) or IsNull(data[i].data) then return end
        
        local roleData = data[i].data
        if not self:IsMyRole(roleData.playerId) then return end

        local roleId = data[i].id
        local roleCampType = UIBattlingDataMgr:GetRoleCampByRoleId(roleId)
        if not BattleInfo:IsUserCamp(roleCampType) then goto continue end --todo 现在只实例玩家卡牌角色
        local goRoleInfoNode = KTool.Instantiate(self.AnimatorRoot.gameObject, self.BattleRoleIInfoNode.gameObject)
        if isNull(self.roleInfoNodeGOList) then
            self.roleInfoNodeGOList = {}
        end
        table.insert(self.roleInfoNodeGOList, goRoleInfoNode)   -- 保存gameObject的引用
        KTool.SetActive(goRoleInfoNode, true)
        goRoleInfoNode.name = string.format("%s_%d", "roleInfo", roleId)
        local roleNode = GetLuaBehaviour(goRoleInfoNode, BattleRoleInfoNode)
        if not IsNull(roleNode) then
            roleNode:Init()
            local ltRoleNode = roleNode.Env
            local roleDataUI =  UIBattlingDataMgr:SetTeamData(BattleInfo.myCamp, roleData, roleId, BattleViewMgr.nowSelfWave)
            local hpCharacter = roleDataUI.hpPreInBattleStart -- 角色初始 HP
            local spCharacter = roleDataUI.spInBattleStart -- 角色初始 SP
            local element = roleDataUI.attrType
            local characterSPMax = isSet(roleData, "maxSP") and roleData.maxSP or 6 -- 角色 SP 上限
            --- 人物信息 Data
            local roleDataInitNode = {
                battleFieldId = roleId,
                AttrType = element,
                HpPreInBattleStart = hpCharacter,
                SpInBattleStart = spCharacter,
                SpMax = characterSPMax,
                roleType = roleCampType, }
            ltRoleNode:SetRoleInfo(roleDataInitNode)
            --- 设置角色 SP 点数
            local roleSPData = {
                roleId = roleId,
                point = spCharacter
            }
            self:OnRoleSPChange(roleSPData)
            table.insert(self.listRoleInfo, ltRoleNode)
        end
        :: continue ::
    end
    
    table.sort(self.listRoleInfo, function (rec1,rec2)
        return rec1.roleId < rec2.roleId
    end)

    local listSummon = {}
    for i, node in ipairs(self.listRoleInfo) do
        if node then
            local roleId = node.roleId
            local roleViewData = BattleViewMgr:FindRoleView(roleId)
            if roleViewData then
                local isPlayer = roleViewData.isPlayer
                if not isPlayer then
                    table.insert(listSummon, node)
                end
            end
            local trans = node.controller.transform
            trans:SetSiblingIndex(checkNumber(i - 1))
        end
    end
    for i, node in ipairs(listSummon) do
        if node then
            local trans = node.controller.transform
            trans:SetAsLastSibling()
        end
    end
end

---OnRoleHpChange
---@param data {roleId = 1, per = 0.5, maxPer = 0.5}
function BattleRoleInfoGroup:OnRoleHpChange(data)
    -- if not self:IsMyRole(data.playerId) then return end
    local index = data.roleId -- 角色Id
    local hpData = data -- 血量信息
    local hpValue = checkNumber(data.per)
    local roleViewData = BattleViewMgr:FindRoleView(index)
    if isNull(roleViewData) then return end
    local isPlayer = checkBool(roleViewData.isPlayer)
    for i = 1, #self.listRoleInfo do
        local roleInfoNode = self.listRoleInfo[i]
        if roleInfoNode.roleAlive and roleInfoNode.roleId == index then
            roleInfoNode:SetRoleHp(hpData)
            -- 播放放大一下的动画
            roleInfoNode:BattlingPerformanceSelectRole()
            -- CoWait.WaitTime(1.5, function ()
            --     if not isNull(roleInfoNode) then
            --         roleInfoNode:BattlingPerformanceCancleRole()
            --     end
            -- end)
            ---召唤兽直接删除预设
            if not isPlayer and hpValue <= 0 then
                KTool.SafeDelete(roleInfoNode.controller.gameObject)
                table.remove(self.listRoleInfo, i)
            end
        end
    end
end

