function BattleRoleInfoGroup:AddBuff(data)
    --- showId 判断
    local buffData = Core:GetBuffData(data.buffId, data.star, data.lv)
    local showIds = buffData.showIds
    if isNull(showIds) or #showIds <= 0 then return end -- 数组数据判断
    local showId = showIds[1] -- 子楠兄 Said ~~
    if Tools.isNullKey(showId) then return end
    local showEffectVo = UIBattlingTools.GetBuffDataPath(showId)
    if isNull(showEffectVo) then return end
    local showText = showEffectVo.showText
    if checkInt(showText) > 0 then return end -- 配表规则 showText > 0 战中不显示
    local passiveShow = showEffectVo.passiveShow
    if checkInt(passiveShow) > 0 then return end -- 配表规则 passiveShow > 0 战中血条不显示图标_Rule_By_MDD
    
    local roleNode
    for i = 1, #self.listRoleInfo do
        if self.listRoleInfo[i].roleId == data.ownerId then
            roleNode = self.listRoleInfo[i]
        end
    end
    if not IsNull(roleNode) then
        --- 角色血条已创建
        self:SetRoleBuffIcon(roleNode, data)
    else
        --- 角色血条为创建/引用丢失, 缓存Buff信息
        UIBattlingCtrlMgr:GetInstance():InsertBuffData(data)
    end
end

function BattleRoleInfoGroup:SetRoleBuffIcon(roleNode, data)
    local buffData = Core:GetBuffData(data.buffId, data.star, data.lv)
    local buffEffectId = buffData.showIds[1] -- 子楠兄 Said ~~ 
    local buffVo = UIBattlingTools.GetBuffDataPath(buffEffectId)
    
    --- 如 效果表现表 无法找到相应 buff 则不实例化数据
    if IsNull(buffVo) then return end
    --- buffIconPath
    local buffIconPath = buffVo.icon --- 获取 buffIcon 资源路径
    if string.isEmpty(buffIconPath) then return end
    local buffTargetId = data.ownerId -- 目标Id
    local buffMainId = data.uid -- buffIndexId
    local buffRemainNum = data.remain -- Buff剩余回合数
    local buffLayer = data.lay -- buff 层数
    local buffTypeId = data.buffId -- BuffTypeId
    local buffFather = roleNode.CharactorBuffRoot
    local buffIconLB = self:ReloadBuffIconLB(buffFather)
    
    if not IsNull(buffIconLB) then
        if buffIconPath then
            -- buffIconLB.Env:SetBuffIconIMG(buffIconPath)
            buffIconLB.Env:SetShowNodeActiveState(true)
            buffIconLB.Env:InitBuffNode(buffTypeId, buffData.round, buffIconPath)
            buffIconLB.Env:SetNodeTxt(buffRemainNum, buffLayer) -- 设置 BuffNode 的 TXT
        end
        
        --- 获取所属人物信息面板的显示状态控制 Txt 节点的显示状态
        --if roleNode.Env:GetCharactorInfoRootShowState() == false then
        --    buffIconLB.Env:SetRoundTxtActiveState(false)
        --end
        --- 判断是否分层
        --if buffRemainNum < 999 then
        --    --- 设置 buffNodeText
        --    buffIconLB.Env:SetNodeTxtFather(self.CharactorInfoNodeLvInfoRoot)
        --end
    end
    UIBattleBuffMgr:ActionOnAddBuff(buffMainId, buffTypeId, buffTargetId, buffLayer, buffIconLB, data.star, data.lv)
    self:SetRoleBuffNodesSequence(roleNode.roleId)
end

---ReloadBuffIconLB
---使用 BuffIcon LB
---@param pos Vector2
function BattleRoleInfoGroup:ReloadBuffIconLB(rect)
    local buffNodeGO = UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.PATH_BUFFNODE_GO, rect)
    local buffNodeLB = GetLuaBehaviour(buffNodeGO, Constants.UIBattlingLuaTablePath.UIBattlingCharactorBuffNode)
    if IsNull(buffNodeLB.Env) then
        buffNodeLB:Init()
    end
    return buffNodeLB
end

function BattleRoleInfoGroup:SetRoleBuffNodesSequence(roleId)
    local buffsList = UIBattleBuffMgr:GetRoleBuffList(roleId)
    local roleNode = self:GetRoleNode(roleId)
    if not isNull(roleNode) then
        roleNode:SetBuffIconSequence(buffsList)
    end
end

function BattleRoleInfoGroup:GetRoleNode(roleId)
    for i, node in pairs(self.listRoleInfo) do
        if node.roleId == roleId then
            return node
        end
    end
    return nil
end

function BattleRoleInfoGroup:ChangeBuff(data)
    local buffMainId = data.uid
    if IsNull(buffMainId) then return end
    UIBattleBuffMgr:ActionOnChangeBuff(data)
end

function BattleRoleInfoGroup:RemoveBuff(data)
    local buffMainId = data.uid -- 移除 buff 的唯一 ID
    local roleId = data.ownerId
    if IsNull(buffMainId) then return end
    UIBattleBuffMgr:ActionOnRemoveBuff(data)
    self:SetRoleBuffNodesSequence(roleId)
end

function BattleRoleInfoGroup:OnRoleSPChange(data)
    -- if not self:IsMyRole(data.playerId) then return end
    local roleId = data.roleId
    local spPoint = data.point
    local roleCampType = UIBattlingDataMgr:GetRoleCampByRoleId(roleId)
    if not BattleInfo:IsUserCamp(roleCampType) then return end
    for i = 1, #self.listRoleInfo do
        if self.listRoleInfo[i].roleId == roleId then
            self.listRoleInfo[i]:SetRoleSP(spPoint)
            break
        end
    end
end

function BattleRoleInfoGroup:RoleTempSPAdd(data)
    -- if not self:IsMyRole(data.playerId) then return end
    local roleId = data.p[1]
    local numSPPoint = data.p[2]
    if checkNumber(numSPPoint) <= 0 then return end
    for i = 1, #self.listRoleInfo do
        if self.listRoleInfo[i].roleId == roleId then
            --- 判断 SP 是否越界
            local boolean, numSP = self.listRoleInfo[i]:AddValueOfRoleSPPoint(numSPPoint)
            if not boolean then return end
            self.listRoleInfo[i]:UpdateRoleSPPoint(numSP)
        end
    end
end

function BattleRoleInfoGroup:ClearTempSPNode()
    --- 还原角色回合开始的 Sp 点数
    for i = 1, #self.listRoleInfo do
        if not IsNull(self.listRoleInfo[i]) then
            self.listRoleInfo[i]:ResetRoleSP()
        end
    end
end

function BattleRoleInfoGroup:OnBattleChangeElement(data)
    -- if not self:IsMyRole(data.playerId) then return end
    local roleId = data.roleId
    local elementType = data.element
    for i = 1, #self.listRoleInfo do
        local roleNode = self.listRoleInfo[i]
        if roleNode then
            if (roleId == roleNode.roleId) and roleNode.roleAlive then
                UIBattlingDataMgr:SetCharacterAttri(roleId, elementType) --设置 mapCharacterAttribute 角色属性字段
                roleNode:SetRoleElementTypeIcon()
                --- 角色相关 SkillCard 转换图标
                --local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
                --battlingDialog:ChangeSkillCardsAttributeTypeByRoleId(roleId, elementType)
                break
            end
        end
    end
end

function BattleRoleInfoGroup:OnRoleShieldChange(data)
    -- if not self:IsMyRole(data.playerId) then return end
    local index = data.roleId
    local shieldValue = data.shieldValue
    local shieldValueMax = data.shieldValueMax
    for i = 1, #self.listRoleInfo do
        if self.listRoleInfo[i].roleId == index then
            local shieldPre = self.listRoleInfo[i]:SetRoleShield(shieldValue, shieldValueMax)
            UIBattlingCtrlMgr:GetInstance():SetCharacterShieldValue(index, shieldValue, shieldValueMax)
            break
        end
    end
end

function BattleRoleInfoGroup:ActionOnPlayerFinishInput()
    xTry(function()
        --print("->123", self.listRoleInfo, table.dump(self.listRoleInfo))
        for i, node in pairs(self.listRoleInfo) do
            if node.roleAlive then
                node:ConversionTempSP()
            end
        end
        self:SetCommonStatus()
    end)
end

function BattleRoleInfoGroup:BattleRequireInputFun()
    ---刷新当前所有人物的 SP 点
    if BattleViewMgr and BattleViewMgr.roleViews then
        for i, roleView in pairs (BattleViewMgr.roleViews) do
            if roleView then
                local roleAlive = not roleView:IsDead()
                if roleAlive then
                    local roleNode = self:GetRoleNode(roleView.id)
                    if not IsNull(roleNode) then
                        roleNode:SetRoleSP(roleView.ultraPoint)
                    end
                end
            end
        end
    end
end

function BattleRoleInfoGroup:IsMyRole(playerId)
    if isNull(playerId) then return true end
    local isMyPlayer = UIBattlingTools.IsMyPlayerId(playerId)
    return self.isMyPlayerGroup == isMyPlayer
end

--- 提前计算移动前后的位置
---@param parent any
function BattleRoleInfoGroup:CalculateTargetPos(parent)
    self.cacheRoleInfoNodePos = {}
    -- 记录头像原本的位置
    for i, node in ipairs(self.roleInfoNodeGOList) do
        self.cacheRoleInfoNodePos[i] = {
            fromPos = node.transform.position
        }
    end
    -- 移动头像到目标parent下面
    for i, node in ipairs(self.roleInfoNodeGOList) do
        KTool.SetParent(node, parent, true)
        node.transform.localPosition = Vector3.New(node.transform.localPosition.x, node.transform.localPosition.y, 0)
    end
    -- 刷新目标parent的layout
    LayoutRebuilder.ForceRebuildLayoutImmediate(parent:GetComponent(typeof(RectTransform)))
    -- 记录头像新的位置
    for i, node in ipairs(self.roleInfoNodeGOList) do
        self.cacheRoleInfoNodePos[i].toPos = node.transform.position
    end
    -- 还原头像到原本的位置
    for i, node in ipairs(self.roleInfoNodeGOList) do
        KTool.SetParent(node, self.AnimatorRoot.gameObject, true)
        node.transform.localPosition = Vector3.New(node.transform.localPosition.x, node.transform.localPosition.y, 0)
    end
end

--- 把头像移动到另外的parent下面
---@param parent any
function BattleRoleInfoGroup:MoveRoleInfoNodeTo(parent)
    if isNull(self.roleInfoNodeGOList) then return end
    if isNull(self.cacheRoleInfoNodePos) then return end
    for i, node in ipairs(self.roleInfoNodeGOList) do
        node.transform:DOMove(self.cacheRoleInfoNodePos[i].toPos, 0.5)
    end
end

--- 把头像从另外的parent下面移动回来
function BattleRoleInfoGroup:MoveRoleInfoNodeBack()
    if isNull(self.roleInfoNodeGOList) then return end
    if isNull(self.cacheRoleInfoNodePos) then return end
    for i, node in ipairs(self.roleInfoNodeGOList) do
        node.transform:DOMove(self.cacheRoleInfoNodePos[i].fromPos, 0.5)
    end
end

function BattleRoleInfoGroup:GetRoleInfoNodeParent()
    return self.AnimatorRoot.gameObject
end

return BattleRoleInfoGroup


